static inline Arx_String Arx_String_init(const char* s) { Arx_String st; st.data = s ? s : ""; st.len = arx_str_len(st.data); return st; }
static inline const char* Arx_String_as_str(Arx_String* self) { return self->data; }
static inline int64_t Arx_String_length(Arx_String* self) { return arx_str_len(self->data); }
static inline int64_t Arx_String_len(Arx_String* self) { return arx_str_len(self->data); }
static inline bool Arx_String_is_empty(Arx_String* self) { return arx_str_len(self->data) == 0; }
static inline Arx_String Arx_String_append(Arx_String* self, const char* s) { return Arx_String_init(arx_str_concat(self->data, s)); }
static inline int64_t Arx_String_byte_at(Arx_String* self, int64_t i) { return arx_str_byte_at(self->data, i); }
static inline const char* Arx_String_char_at(Arx_String* self, int64_t i) { return __arx_byte_chr(arx_str_byte_at(self->data, i)); }
static inline const char* Arx_String_get(Arx_String* self, int64_t i) { return __arx_byte_chr(arx_str_byte_at(self->data, i)); }
static inline bool Arx_String_contains(Arx_String* self, const char* s) { return arx_str_contains(self->data, s); }
static inline bool Arx_String_starts_with(Arx_String* self, const char* s) { return arx_str_starts_with(self->data, s); }
static inline bool Arx_String_ends_with(Arx_String* self, const char* s) { return arx_str_ends_with(self->data, s); }
static inline int64_t Arx_String_index_of(Arx_String* self, const char* s) { return arx_str_find(self->data, s); }
static inline Arx_String Arx_String_slice(Arx_String* self, int64_t a, int64_t b) { return Arx_String_init(__arx_bstr_slice(self->data, a, b)); }
static inline Arx_List_str Arx_String_split(Arx_String* self, const char* d) { return __arx_bstr_split(self->data, d); }
static inline Arx_String Arx_String_trim(Arx_String* self) { return Arx_String_init(arx_str_trim(self->data)); }
static inline Arx_String Arx_String_to_upper(Arx_String* self) { return Arx_String_init(arx_str_to_upper(self->data)); }
static inline Arx_String Arx_String_to_lower(Arx_String* self) { return Arx_String_init(arx_str_to_lower(self->data)); }
static inline Arx_String Arx_String_replace(Arx_String* self, const char* o, const char* n) { return Arx_String_init(arx_str_replace(self->data, o, n)); }
static inline Arx_String Arx_String_repeat(Arx_String* self, int64_t n) { return Arx_String_init(arx_str_repeat(self->data, n)); }

